from pathlib import Path
p=Path('temp/native-source-offline/publication-attribution')
s=(p/'controller.before.mjs').read_text()
needle=" const {getPaperBytes}=await import('/src/engine/src/paper/paperLoader.ts');"
insert=""" const wrap=(owner,name,label)=>{const original=owner[name];if(typeof original!=='function')throw Error('Missing attribution method '+label);let serial=0;owner[name]=function(...args){const id=++serial;add(label+':start',{id});try{const value=original.apply(this,args);if(value&&typeof value.then==='function')return value.then(result=>{add(label+':end',{id});return result},error=>{add(label+':reject',{id,error:String(error)});throw error});add(label+':end',{id});return value}catch(error){add(label+':reject',{id,error:String(error)});throw error}}};const {CanonicalRoomTileBridge}=await import('/src/engine/src/webgpuCanonical/roomTileBridge.ts');const {AccumulationBuffer}=await import('/src/engine/src/buffers/AccumulationBuffer.ts');const {CanonicalSingleTileFinish}=await import('/src/engine/src/webgpuCanonical/finishTile.ts');wrap(CanonicalRoomTileBridge.prototype,'copyByCanvas','bridge.canvas');wrap(CanonicalRoomTileBridge.prototype,'copyByReadback','bridge.readback');wrap(AccumulationBuffer.prototype,'restoreCanvasPixels','gl.restoreCanvasPixels');wrap(CanonicalWatercolorWebGpu.prototype,'readField','backend.readField');for(const name of ['encode','encodeLive'])wrap(CanonicalSingleTileFinish.prototype,name,'composite.'+name);const create=CanonicalWatercolorWebGpu.create;CanonicalWatercolorWebGpu.create=async function(...args){const result=await create.apply(this,args);wrap(result.device.queue,'submit','queue.submit');wrap(result.device.queue,'onSubmittedWorkDone','queue.completion');return result}; const {getPaperBytes}=await import('/src/engine/src/paper/paperLoader.ts');"""
assert s.count(needle)==1
s=s.replace(needle,insert)
s=s.replace('[[500,500],[500,540],[500,580]]', '[[500,490],[500,530],[500,570],[500,610]]')
(p/'controller.mjs').write_text(s)
